from __future__ import annotations

import base64
import hashlib
import subprocess
import zlib
from pathlib import Path

EXPECTED_PATCH_SHA256 = "c57ec53ee38cab97aed4815aad5bac0ae139ef90af99dfb139b462ac6a76746a"
PATCH_ZLIB_BASE64 = """

"""


def main() -> None:
    patch = zlib.decompress(base64.b64decode(PATCH_ZLIB_BASE64))
    if hashlib.sha256(patch).hexdigest() != EXPECTED_PATCH_SHA256:
        raise SystemExit("reviewed patch digest mismatch")
    patch_path = Path("/tmp/hardening-batch.patch")
    patch_path.write_bytes(patch)
    subprocess.run(["git", "apply", "--check", str(patch_path)], check=True)
    subprocess.run(["git", "apply", "--index", str(patch_path)], check=True)


if __name__ == "__main__":
    main()
